package com.internal.admin;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.Authentication;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.context.annotation.Bean;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.List;

@SpringBootApplication
public class AdminServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(AdminServiceApplication.class, args);
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.csrf().disable()
            .authorizeRequests()
            .antMatchers("/actuator/health").permitAll()
            .antMatchers("/api/admin/**").hasRole("ADMIN")
            .antMatchers("/api/user/**").hasAnyRole("USER", "ADMIN")
            .anyRequest().authenticated()
            .and().httpBasic();
        return http.build();
    }
}

@RestController
@RequestMapping("/api")
class UserController {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    // Normal user endpoint - fetch own profile
    @GetMapping("/user/profile")
    public Map<String, Object> getProfile() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth.getName();
        List<Map<String, Object>> results = jdbcTemplate.queryForList(
            "SELECT username, email, role FROM users WHERE username = ?", username);
        return results.isEmpty() ? Map.of("error", "not found") : results.get(0);
    }

    // User can update their own display name
    @PostMapping("/user/profile")
    public Map<String, Object> updateProfile(@RequestBody Map<String, String> body) {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        String username = auth.getName();
        String displayName = body.get("displayName");
        jdbcTemplate.update("UPDATE users SET display_name = ? WHERE username = ?",
            displayName, username);
        return Map.of("status", "updated");
    }

    // VULNERABILITY: role update endpoint lacks proper authorization check
    // It checks for authentication but the @PreAuthorize is commented out
    // and the manual check uses a request header that can be spoofed
    @PutMapping("/user/role")
    // @PreAuthorize("hasRole('ADMIN')")
    public Map<String, Object> updateRole(@RequestBody Map<String, String> body,
                                           HttpServletRequest request) {
        // "Internal" check - trusts X-Internal-Service header
        String internalHeader = request.getHeader("X-Internal-Service");
        if (internalHeader == null || !internalHeader.equals("role-management-svc")) {
            // Fallback: check if caller has any valid authentication (not admin-only!)
            Authentication auth = SecurityContextHolder.getContext().getAuthentication();
            if (auth == null || !auth.isAuthenticated()) {
                return Map.of("error", "unauthorized");
            }
        }

        String targetUser = body.get("username");
        String newRole = body.get("role");

        // No validation that the authenticated user can only change their own role
        // Any authenticated user can escalate any user to ADMIN
        jdbcTemplate.update("UPDATE users SET role = ? WHERE username = ?",
            newRole, targetUser);

        return Map.of("status", "role_updated", "username", targetUser, "newRole", newRole);
    }

    @GetMapping("/admin/users")
    @PreAuthorize("hasRole('ADMIN')")
    public List<Map<String, Object>> listUsers() {
        return jdbcTemplate.queryForList("SELECT username, email, role FROM users");
    }

    // Looks suspicious but is actually safe - parameterized query
    @GetMapping("/user/search")
    public List<Map<String, Object>> searchUsers(@RequestParam String q) {
        return jdbcTemplate.queryForList(
            "SELECT username, display_name FROM users WHERE display_name LIKE ?",
            "%" + q + "%");
    }
}
